// === Gegenprobe zum Scan-Flow – bewusst ein zweiter, unabhaengiger Weg ===
// Der Scan-Flow liest REST orders.json. Dieser hier liest GraphQL orders.
// Gleiche Frage, andere Implementierung: nur so faengt die Gegenprobe auch
// einen Fehler im Fetch selbst und nicht nur einen in den Daten.

const TAGE = 14;
const jetzt = new Date();
const von = new Date(jetzt.getTime() - TAGE * 24 * 60 * 60 * 1000);

const CONFIG = {
  shop: 'vdzvc0-nd',
  apiVersion: '2024-10',

  tage: TAGE,

  // Grober Serverfilter: nur das Datum. Shopify liest das in Shop-Zeitzone
  // (also 00:00 +02:00) und damit etwas weiter als noetig – gewollt.
  queryDatum: von.toISOString().slice(0, 10),

  // Exakte Grenze, identisch zum Scan-Flow. Darauf wird clientseitig geschnitten.
  cutoffIso: von.toISOString(),

  seitenGroesse: 250,

  // Notbremse: verhindert eine Endlosschleife bei kaputtem Cursor.
  maxSeiten: 40,

  // Bestellungen mit Refunds koennen viele sein – Detailzeilen begrenzen.
  detailLimitRefunds: 50
};

return [{ json: { config: CONFIG } }];

// Sammelbehaelter leeren. staticData ueberlebt Executions.
const staticData = $getWorkflowStaticData('global');

staticData.gp = {
  seiten: 0,
  gesamt: 0,
  ausserhalb: 0,
  negativ: [],
  positiv: [],
  unlesbar: [],
  mitRefunds: [],
  anzahlMitRefunds: 0,
  summeRefunds: 0,
  aelteste: null,
  neueste: null
};

return [{ json: { cursor: null, hasNext: true, seite: 0 } }];

const config = $('Config').first().json.config;
const cursor = $input.first().json.cursor || null;

// sortKey CREATED_AT + reverse: neueste zuerst, wie bei der manuellen Pruefung.
const query = `query($cursor: String) {
  orders(
    first: ${config.seitenGroesse}
    after: $cursor
    query: "created_at:>=${config.queryDatum}"
    sortKey: CREATED_AT
    reverse: true
  ) {
    edges {
      node {
        id
        name
        createdAt
        displayFinancialStatus
        totalPriceSet       { presentmentMoney { amount currencyCode } }
        totalRefundedSet    { presentmentMoney { amount } }
        totalOutstandingSet { presentmentMoney { amount currencyCode } }
      }
    }
    pageInfo { hasNextPage endCursor }
  }
}`;

return [{
  json: {
    cursor,
    gqlBody: JSON.stringify({ query, variables: { cursor } })
  }
}];

const resp = $input.first().json;

// Shopify antwortet auf GraphQL-Fehler mit HTTP 200, der HTTP-Node schlaegt
// also nicht fehl. Hier hart abbrechen: eine halbe Gegenprobe ist wertlos.
if (Array.isArray(resp?.errors) && resp.errors.length) {
  throw new Error('GraphQL-Fehler: ' + JSON.stringify(resp.errors));
}

const conn = resp?.data?.orders;
if (!conn) {
  throw new Error('Keine Orders-Antwort: ' + JSON.stringify(resp).slice(0, 500));
}

const config = $('Config').first().json.config;
const staticData = $getWorkflowStaticData('global');
const gp = staticData.gp;

const cutoffMs = new Date(config.cutoffIso).getTime();
gp.seiten++;

const knoten = (conn.edges || []).map(e => e.node);

for (const o of knoten) {
  // Serverfilter ist nur datumsgenau -> hier exakt auf das Fenster des
  // Scan-Flows schneiden, sonst vergleicht man zwei verschiedene Mengen.
  if (new Date(o.createdAt).getTime() < cutoffMs) {
    gp.ausserhalb++;
    continue;
  }

  gp.gesamt++;
  if (!gp.neueste || o.createdAt > gp.neueste) gp.neueste = o.createdAt;
  if (!gp.aelteste || o.createdAt < gp.aelteste) gp.aelteste = o.createdAt;

  const satz = {
    orderId: String(o.id).split('/').pop(),
    orderName: o.name,
    createdAt: o.createdAt,
    status: o.displayFinancialStatus,
    gesamtpreis: o.totalPriceSet?.presentmentMoney?.amount,
    saldo: o.totalOutstandingSet?.presentmentMoney?.amount,
    erstattet: o.totalRefundedSet?.presentmentMoney?.amount,
    currency: o.totalOutstandingSet?.presentmentMoney?.currencyCode
      || o.totalPriceSet?.presentmentMoney?.currencyCode,
    adminUrl: `https://admin.shopify.com/store/${config.shop}/orders/${String(o.id).split('/').pop()}`
  };

  // null/'' waeren bei Number() eine 0 und wuerden als "ausgeglichen" durchgehen.
  const roh = o.totalOutstandingSet?.presentmentMoney?.amount;
  const saldo = (roh === null || roh === undefined || roh === '') ? NaN : Number(roh);
  if (!Number.isFinite(saldo)) {
    gp.unlesbar.push({ ...satz, grund: 'totalOutstandingSet unlesbar' });
  } else if (saldo < 0) {
    gp.negativ.push(satz);
  } else if (saldo > 0) {
    gp.positiv.push(satz);
  }

  const erstattet = Number(o.totalRefundedSet?.presentmentMoney?.amount || 0);
  if (erstattet > 0) {
    gp.anzahlMitRefunds++;
    gp.summeRefunds += erstattet;
    if (gp.mitRefunds.length < config.detailLimitRefunds) gp.mitRefunds.push(satz);
  }
}

const serverHatMehr = !!conn.pageInfo?.hasNextPage;
const limitErreicht = gp.seiten >= config.maxSeiten;

return [{
  json: {
    cursor: conn.pageInfo?.endCursor || null,
    hasNext: serverHatMehr && !limitErreicht,
    abgebrochen: serverHatMehr && limitErreicht,
    seite: gp.seiten,
    seiteBestellungen: knoten.length,
    imFensterBisher: gp.gesamt,
    negativBisher: gp.negativ.length
  }
}];

const config = $('Config').first().json.config;
const staticData = $getWorkflowStaticData('global');
const gp = staticData.gp;
const letzte = $input.first().json;

const summe = (liste) => liste
  .reduce((s, r) => s + Math.abs(Number(r.saldo || 0)), 0)
  .toFixed(2);

const vollstaendig = !letzte.abgebrochen;
const saldoNull = gp.gesamt - gp.negativ.length - gp.positiv.length - gp.unlesbar.length;

// Das ist der eigentliche Zweck des Reports: eine Aussage, die man gegen den
// Scan-Flow halten kann, statt nur einer Zahl.
let urteil;
if (!vollstaendig) {
  urteil = 'UNVOLLSTAENDIG – maxSeiten erreicht, Aussage nicht belastbar';
} else {
  const teile = [gp.negativ.length === 0
    ? 'Scan-Flow muss 0 Kandidaten melden'
    : 'Scan-Flow muss ' + gp.negativ.length + ' Kandidaten melden (' + summe(gp.negativ) + ' offen)'];
  // Unlesbare Salden zusaetzlich, nicht anstelle der Kandidatenzahl.
  if (gp.unlesbar.length) {
    teile.push('PRUEFEN: ' + gp.unlesbar.length + ' Bestellung(en) mit unlesbarem Saldo');
  }
  urteil = teile.join(' – ');
}

const zusammenfassung = {
  zeile: 'ZUSAMMENFASSUNG',
  lauf: new Date().toISOString(),
  quelle: 'GraphQL orders – unabhaengig vom REST-Fetch des Scan-Flows',
  urteil,
  paginationVollstaendig: vollstaendig,

  zeitraumTage: config.tage,
  cutoff: config.cutoffIso,
  serverFilter: 'created_at:>=' + config.queryDatum,
  aeltesteBestellung: gp.aelteste,
  neuesteBestellung: gp.neueste,

  seitenGeholt: gp.seiten,
  bestellungenImFenster: gp.gesamt,
  vorCutoffVerworfen: gp.ausserhalb,

  saldoNegativ: gp.negativ.length,
  summeNegativ: summe(gp.negativ),
  saldoPositiv: gp.positiv.length,
  summePositiv: summe(gp.positiv),
  saldoNull,
  saldoUnlesbar: gp.unlesbar.length,

  bestellungenMitRefunds: gp.anzahlMitRefunds,
  summeErstattet: gp.summeRefunds.toFixed(2)
};

const sortiert = (liste) => [...liste]
  .sort((a, b) => Math.abs(Number(b.saldo || 0)) - Math.abs(Number(a.saldo || 0)));

return [
  { json: zusammenfassung },
  ...sortiert(gp.negativ).map(r => ({ json: { zeile: 'SALDO_NEGATIV', ...r } })),
  ...sortiert(gp.positiv).map(r => ({ json: { zeile: 'SALDO_POSITIV', ...r } })),
  ...gp.unlesbar.map(r => ({ json: { zeile: 'UNLESBAR', ...r } })),
  ...gp.mitRefunds.map(r => ({ json: { zeile: 'MIT_REFUND', ...r } }))
];
